import {COW} from './cow-config.js';import {WATER} from './config.js';import {cowSupply} from './cow-state.js';import {cowEffectiveGrade} from './cow-storage.js';
/** All usable supplies, including restricted balances that are not yet placed. @param {import('./engine.js').State} state */
export function cowAccessibleSupply(state){const g=state.cow;return {feedG:g?cowSupply(g.feedTrough)+g.feedStoreG+g.starterRation.feedG+g.recoveryRation.feedG:0,waterMl:g?cowSupply(g.waterTrough)+Math.floor(state.water*1000)+g.starterRation.waterMl+g.recoveryRation.waterMl:0};}
/** Free cleaning/discarding can unblock milking; those chores must precede aid. @param {import('./engine.js').State} state */
export function cowMilkAvailableNow(state){const g=state.cow;if(!g)return false;if(g.lots.some(l=>!!cowEffectiveGrade(l)))return true;return g.cows.some(c=>c.priorCalving&&c.lactationStatus==='lactating'&&c.milkReadyMl>0&&(c.lastMilkingTick<0||state.tick-c.lastMilkingTick>=COW.sessionSpacing)&&(c.milkingDay!==Math.floor(state.tick/24)||c.sessions<COW.sessionsDay));}
/** Eligibility is rechecked at both ends, with no forced sale of other farm assets. @param {import('./engine.js').State} state @param {boolean} [completion] */
export function cowRecoveryReason(state,completion=false){const g=state.cow;if(!g?.visited)return 'cowNotVisited';if(completion&&!g.recovery.active)return 'cowNoCareJob';if(!completion&&g.recovery.active)return 'cowCareJobActive';if(g.recoveryRation.feedG>0||g.recoveryRation.waterMl>0)return 'cowRecoveryRationPending';if(state.tick<g.recovery.nextEligibleTick)return 'cowCareJobCooldown';const supply=cowAccessibleSupply(state),feedNeed=g.cows.reduce((n,c)=>n+Math.floor((COW.feedDayG+c.feedDemandRemainder)/24),0),waterNeed=g.cows.length*(state.weather==='hot'?COW.hotWaterDayMl:COW.waterDayMl)/24,missingFeed=supply.feedG<feedNeed,missingWater=supply.waterMl<waterNeed;if(!missingFeed&&!missingWater)return 'cowUseSuppliesFirst';if(cowMilkAvailableNow(state))return 'cowUseMilkFirst';const cost=(missingFeed?COW.feedBagPrice:0)+(missingWater?Math.ceil(Math.min(WATER.refillLitres,WATER.tankCapacity-state.water)/WATER.refillLitres*WATER.refillCost):0);if(state.coins>=cost)return 'cowUseMarketFirst';if(completion&&state.tick-g.recovery.startedTick<COW.recoveryHours)return 'cowCareJobWait';return '';}
/** Grants bounded Cow-only aid, never Coins or shared water. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./engine.js').DomainEvent[]} events @param {import('./cow-runtime.js').CowTransaction} transact */
export function applyCowRecovery(state,command,events,transact){const complete=command.type==='completeCowCareJob',reason=cowRecoveryReason(state,complete);if(reason)return reason;const g=state.cow;if(!g)return 'cowNotVisited';if(!complete){g.recovery.episode++;g.recovery.active=true;g.recovery.startedTick=state.tick;events.push({type:'cowCareJobStarted'});return '';}const supplies=cowAccessibleSupply(state),feedG=Math.max(0,g.cows.length*COW.feedDayG-supplies.feedG),waterMl=Math.max(0,g.cows.length*COW.hotWaterDayMl-supplies.waterMl);g.recoveryRation.feedG+=feedG;g.recoveryRation.waterMl+=waterMl;g.stats.recoveryFeedGrantedG+=feedG;g.stats.recoveryWaterGrantedMl+=waterMl;g.recovery.active=false;g.recovery.completed++;g.recovery.lastCompleteTick=state.tick;g.recovery.nextEligibleTick=state.tick+24;transact(state,'cow_recovery_grant',0,'cow.recovery.'+g.recovery.episode);events.push({type:'cowCareJobCompleted'});return '';}
